`timescale 1fs/1fs
//======================================================================
// ro_vco_rnm -- real-number model of a voltage-controlled oscillator.
//
// AUTO-GENERATED by spice2rnm (Veylon Systems).  Edits will be overwritten.
//
// This block's function is a FREQUENCY, so there is no H(s) here and no
// fixed integration timestep. The output edge is scheduled from the control
// voltage in effect at the time:
//
//     always begin #(half_period(cont)) clk = ~clk; end
//
// which costs one event per half cycle instead of one per timestep, and
// keeps phase continuous across a control change: the edge already
// scheduled is not retimed, exactly as a real oscillator behaves.
//
// Tuning curve: 16 points measured from SPICE over 0.49..2.80 V
// (16.7..804.5 MHz). Each point is the period counted over whole
// cycles of a transient whose timestep is a fixed fraction of that point's
// own period, re-run at half that step to show the number stopped moving.
// Held-out error on the 14 midpoints between them: 4.986% of period (1774.5 ps), worst at 2.7689 V.
// In the MEASURED OPERATING BAND 1.7943..1.9074 V, taken from a golden
// co-simulation run before this model existed: 0.002% (0.1 ps) over 5
// held-out point(s), worst at 1.8932 V.
// Measurement convergence: halving the timestep moved the
// worst point by 0.015%. The held-out score above is
// interpolation error ONLY -- it compares points measured one
// way against a table built the same way, so it is blind to
// anything the measurement gets wrong at every point alike.
// This figure is that part.
//
// The table is CLAMPED at both ends. Inside a loop the control voltage
// leaves this range during acquisition; saturating is the honest answer
// there, where a fitted polynomial would extrapolate to a frequency the
// circuit cannot produce.
//======================================================================
module ro_vco_rnm #(
  // Measured, at the control voltage this block was characterized around.
  parameter real VDD_NOM  = 3.3,   // volts
  parameter real DFDV_SUP = 4.506321519e+08,  // Hz per volt of supply
  // Sub-steps per half cycle. 16 tracks a fast-moving input; 1 restores
  // the one-event-per-half-cycle scheduling, which is right when nothing
  // on this block's inputs moves within a cycle.
  parameter int  SUB = 16,
  // RMS PERIOD JITTER, as a fraction of the period. Zero unless a
  // measurement asked for it -- see the header note above the table.
  parameter real JITTER_FRAC = 0.000000000e+00,
  parameter int  JITTER_SEED = 1
) (
  input  real  cont,
  // THE SUPPLY IS AN INPUT, because the circuit's frequency depends on it
  // about as strongly as on the control: measured at 450.6 MHz/V
  // against roughly the same from the tuning port, and opposite in sign.
  // A model without this pin is not a slightly simplified oscillator, it
  // is one that cannot show what a supply droop does -- and on this ring
  // 100 mV of droop is worth about 45.06 MHz.
  input  real  vdd,
  output logic clk
);

  localparam int N = 16;
  real VC [0:N-1];
  real FO [0:N-1];

  // Loaded by the function that reads it, on first use -- NOT by an
  // initial block. IEEE 1800 leaves the order of initial and always
  // procedures at time zero undefined, and a reader that runs first would
  // see an all-zero table.
  bit tab_loaded;
  function automatic void load_tab();
      VC[0] = 0.495000; FO[0] = 8.044728186e+08;
      VC[1] = 0.783750; FO[1] = 7.353222574e+08;
      VC[2] = 1.072500; FO[2] = 6.634459647e+08;
      VC[3] = 1.361250; FO[3] = 5.803862641e+08;
      VC[4] = 1.650000; FO[4] = 4.774032573e+08;
      VC[5] = 1.794299; FO[5] = 4.214828487e+08;
      VC[6] = 1.822570; FO[6] = 4.104917296e+08;
      VC[7] = 1.850841; FO[7] = 3.995364568e+08;
      VC[8] = 1.879112; FO[8] = 3.886351736e+08;
      VC[9] = 1.907383; FO[9] = 3.778016262e+08;
      VC[10] = 1.938750; FO[10] = 3.658689447e+08;
      VC[11] = 2.227500; FO[11] = 2.570119652e+08;
      VC[12] = 2.516250; FO[12] = 1.366251648e+08;
      VC[13] = 2.660625; FO[13] = 7.416278165e+07;
      VC[14] = 2.732812; FO[14] = 4.240882586e+07;
      VC[15] = 2.805000; FO[15] = 1.673948453e+07;
    tab_loaded = 1'b1;
  endfunction

  function automatic real freq_of(input real v);
    int  k;
    real t;
    if (!tab_loaded) load_tab();
    if (v <= VC[0])   return FO[0];
    if (v >= VC[N-1]) return FO[N-1];
    for (k = 0; k < N-1; k++) begin
      if (v >= VC[k] && v <= VC[k+1]) begin
        t = (v - VC[k]) / (VC[k+1] - VC[k]);
        return FO[k] + t * (FO[k+1] - FO[k]);
      end
    end
    return FO[N-1];
  endfunction

  // An UNCONNECTED supply reads as 0.0, which would put the frequency
  // somewhere the circuit cannot go. Treated as nominal and said out loud
  // once: silently substituting would hide a mis-wired instance, and
  // failing outright would break every composition written before this
  // port existed.
  bit vdd_warned = 1'b0;
  function automatic real supply_eff(input real vs);
    if (vs > 0.0) return vs;
    if (!vdd_warned) begin
      vdd_warned = 1'b1;
      $display("[%m] vdd is unconnected or zero; using VDD_NOM=%0.4g V. Connect it to see supply sensitivity.", VDD_NOM);
    end
    return VDD_NOM;
  endfunction

  // An explicit LCG rather than $urandom, so a run is reproducible from
  // its seed on any simulator and two runs of the same model can be
  // compared. Not a good generator; good enough for a perturbation whose
  // only required property is its variance.
  int unsigned __jrng = 1;
  function automatic real __u01();
    __jrng = __jrng * 32'd1664525 + 32'd1013904223;
    return (real'(__jrng) + 0.5) / 4294967296.0;
  endfunction
  function automatic real __gauss();
    real u1, u2;
    u1 = __u01();
    u2 = __u01();
    return $sqrt(-2.0 * $ln(u1)) * $cos(6.283185307179586 * u2);
  endfunction

  // The next half cycle's phase target. One half cycle is a phase of 1,
  // so crossing at 1+g lengthens that half cycle by the fraction g --
  // which is how a DURATION is perturbed without ever asking the
  // scheduler for a negative delay.
  //
  // Floored well above zero: a sigma large enough to drive the target
  // negative would not model a noisy oscillator, it would spin the
  // scheduler.
  function automatic real __next_thr();
    real g;
    if (JITTER_FRAC <= 0.0) return 1.0;
    g = 1.0 + 1.4142135623730951 * JITTER_FRAC * __gauss();
    return (g < 0.2) ? 0.2 : g;
  endfunction

  // Half period in the module's time unit (1 fs).
  function automatic real half_period_fs(input real v, input real vs);
    real f;
    f = freq_of(v) + DFDV_SUP * (supply_eff(vs) - VDD_NOM);
    // A zero delay here would spin the scheduler forever rather than model
    // a stopped oscillator, so floor it at the slowest tabulated rate.
    if (f <= 0.0) return 1.0e15 / (2.0 * 1.673948453e+07);
    return 1.0e15 / (2.0 * f);
  endfunction

  initial clk = 1'b0;

  // PHASE IS INTEGRATED, not sampled once per half cycle.
  //
  // Scheduling a whole half period from the input in effect at the instant
  // the edge fires is exact for an input that moves slowly, and wrong for
  // one that moves fast: an oscillator's phase is the integral of its
  // instantaneous frequency, so a circuit AVERAGES a fast-moving control
  // over the cycle and a single sample does not. Measured on the reference
  // ring: the sampling form produced 3.37x the period jitter the
  // transistors did for the same injected control noise, where
  // sqrt(T_half/tau) = sqrt(1250ps/100ps) = 3.54 predicts 3.5. The
  // integrating form reproduces it to within 8%.
  //
  // The crossing is INTERPOLATED inside the sub-step rather than rounded
  // to it. Rounding put every edge on a sub-step grid and gave the model a
  // 19.3 ps jitter floor with no noise present at all -- dt/sqrt(12), the
  // rms of a uniform quantiser, which is the sub-step and not the circuit.
  //
  // COST, stated because it is the trade: SUB events per half cycle
  // instead of one. Set SUB to 1 for the cheap scheduling where the inputs
  // are known to move slowly.
  real phase_clk;
  real dt_fs, incr, frac, thr;

  initial begin
    phase_clk = 0.0;
    __jrng = JITTER_SEED;
    thr = __next_thr();
    dt_fs = half_period_fs(cont, vdd) / SUB;
    forever begin
      incr = 2.0 * (1.0e15 / (2.0 * half_period_fs(cont, vdd)))
             * (dt_fs * 1.0e-15);
      if (phase_clk + incr >= thr) begin
        frac = (thr - phase_clk) / incr;
        #(dt_fs * frac);
        clk = ~clk;
        phase_clk = 0.0;
        // Redrawn per half cycle, so the perturbations accumulate and the
        // edge times random-walk -- which is what a free-running
        // oscillator does.
        thr = __next_thr();
        #(dt_fs * (1.0 - frac));
        phase_clk = incr * (1.0 - frac);
      end else begin
        #(dt_fs);
        phase_clk = phase_clk + incr;
      end
    end
  end


`ifndef SPICE2RNM_NO_ASSERT
  //--------------------------------------------------------------------
  // Validity domain, from the measurements that built this model.
  //
  // These state where the evidence applies. Outside it the model does
  // not extrapolate -- it CLAMPS, and keeps returning a plausible
  // number -- so being told once is the difference between a wrong
  // answer you can see and one you cannot.
  //
  // Compile out with +define+SPICE2RNM_NO_ASSERT.
  //--------------------------------------------------------------------
  localparam real DOMAIN_LO  = 0.495;
  localparam real DOMAIN_HI  = 2.805;
  localparam real DOMAIN_EPS = 0.0; // exact -- no stimulus here overshoots, so no margin is earned
  bit domain_reported = 1'b0;

  always @(cont) begin : domain_check
    a_input_domain: assert (cont >= DOMAIN_LO - DOMAIN_EPS && cont <= DOMAIN_HI + DOMAIN_EPS)
    else if (!domain_reported) begin
      domain_reported = 1'b1;
      $warning("%m: input %0.6g V is outside the characterized range %0.6g..%0.6g V. the table clamps at its measured end points, so this model keeps running and returns the endpoint value -- it is not extrapolating, and it is no longer evidence. Reported once.",
               cont, DOMAIN_LO, DOMAIN_HI);
    end
  end

  bit in_nan_reported = 1'b0;

  always @(cont) begin : input_health
    // NaN is the one value that is not equal to itself.
    a_input_finite: assert (cont == cont)
    else if (!in_nan_reported) begin
      in_nan_reported = 1'b1;
      $error("%m: control input is NaN -- whatever drives this model diverged. Reported once.");
    end
  end
`endif

endmodule : ro_vco_rnm
